static int r8152_aldps_en(struct r8152 *tp, bool enable)
{
	int ret;

	if (enable) {
		ret = ocp_reg_write(tp, OCP_ALDPS_CONFIG, ENPWRSAVE | ENPDNPS |
							  LINKENA | DIS_SDSAVE);
	} else {
		ret = ocp_reg_write(tp, OCP_ALDPS_CONFIG, ENPDNPS | LINKENA |
							  DIS_SDSAVE);
		msleep(20);
	}
	return ret;
}
